sp_widget.client_script:
api.controller = function() {
  /* widget controller */
  var c = this;

  // počkaj, kým sa DOM widgetu načíta
  c.$onInit = function() {
    // koreň elementu widgetu
    var rootEl = c.$element[0];

    // nájdi input a button
    var input = rootEl.querySelector('.me-search-input');
    var btn = rootEl.querySelector('.me-search-btn');

    // pridaj klik event na tlačidlo
    if (btn && input) {
      btn.addEventListener('click', function() {
        var query = input.value.trim();
        if (query) {
          // presmerovanie na stránku s výsledkami (prípadne API call)
          window.location.href = '/search_results_mep?query=' + encodeURIComponent(query);
        } else {
          alert('Please enter a search term.');
        }
      });

      // umožni vyhľadávať aj po stlačení Enter
      input.addEventListener('keypress', function(e) {
        if (e.key === 'Enter') {
          btn.click();
        }
      });
    }
  };
};

sp_widget.css:
.me-header-container {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 10px 20px;
  background-color: var(--navbar-bg); /* z theme */
  color: var(--text-color);           /* z theme */
  font-family: Arial, sans-serif;     /* môžeš použiť z theme, ak máš premennú */
}

.me-header-left img {
  height: 50px;
}

.me-header-center nav a {
  margin: 0 15px;
  color: var(--navbar-link-color); /* z theme */
  text-decoration: none;
  font-weight: bold;
}

.me-header-center nav a:hover,
.me-header-center nav a.active {
  color: var(--navbar-link-hover-color); /* z theme */
  text-decoration: underline;
}

/* Dropdown */
.dropdown {
  display: inline-block;
  position: relative;
}

.dropdown-content {
  display: none;
  position: absolute;
  background-color: var(--navbar-bg);
  min-width: 120px;
  z-index: 1;
}

.dropdown:hover .dropdown-content {
  display: block;
}

.dropdown-content a {
  display: block;
  padding: 5px 10px;
  color: var(--text-color);
  text-decoration: none;
}

.dropdown-content a:hover {
  background-color: var(--success-color); /* z theme */
}

/* Search input + button */
.me-header-right input.me-search-input {
  padding: 5px 10px;
  border-radius: 4px;
  border: none;
  margin-right: 5px;
}

.me-header-right button.me-search-btn {
  padding: 5px 10px;
  background-color: var(--btn-bg);   /* z theme */
  border: none;
  border-radius: 4px;
  cursor: pointer;
  font-weight: bold;
  color: var(--btn-color);           /* z theme */
}

.me-header-right button.me-search-btn:hover {
  background-color: var(--success-color); /* z theme */
}

.me-header-container {
  position: sticky; /* alebo fixed */
  top: 0;
  left: 0;
  width: 100%;
  z-index: 9999; /* musí byť vyššie ako všetky elementy hero/poster */
  background-color: var(--navbar-bg); /* aby bol krytý podklad */
}
